// Схема водопроводной сети Актау, построенная по дорожному графу OpenStreetMap.
// Магистрали (trunk) — основные водоводы, распределительные (distribution) — внутриквартальные линии.
// Координаты хранятся в порядке GeoJSON: [lng, lat].

export type PipeCondition = 'good' | 'fair' | 'poor' | 'critical';
export type PipeKind = 'trunk' | 'distribution';

export type PipeSegment = {
  id: string;
  name: string;
  type: PipeKind;
  diameter: number; // мм
  material: string;
  yearBuilt: number;
  condition: PipeCondition;
  coords: [number, number][];
};

export const pipeConditionLabel: Record<PipeCondition, string> = { good: 'Хорошее', fair: 'Удовлетворительное', poor: 'Изношено', critical: 'Аварийное' };
export const pipeConditionColor: Record<PipeCondition, string> = { good: '#1fa38b', fair: '#2196e0', poor: '#f0ac43', critical: '#df4f62' };
export const pipeKindLabel: Record<PipeKind, string> = { trunk: 'Магистраль', distribution: 'Распределительная' };

